import json, hashlib, base64
from Crypto.Cipher import AES

P = int(
 "FFFFFFFFFFFFFFFFC90FDAA22168C234C4C6628B80DC1CD1"
 "29024E088A67CC74020BBEA63B139B22514A08798E3404DD"
 "EF9519B3CD3A431B302B0A6DF25F14374FE1356D6D51C245"
 "E485B576625E7EC6F44C42E9A637ED6B0BFF5CB6F406B7ED"
 "EE386BFB5A899FA5AE9F24117C4B1FE649286651ECE45B3D"
 "C2007CB8A163BF0598DA48361C55D39A69163FA8FD24CF5F"
 "83655D23DCA3AD961C62F356208552BB9ED529077096966D"
 "670C354E4ABC9804F1746C08CA18217C32905E462E36CE3B"
 "E39E772C180E86039B2783A2EC07A28FB5C55DF06F4C52C9"
 "DE2BCBF6955817183995497CEA956AE515D2261898FA0510"
 "15728E5A8AACAA68FFFFFFFFFFFFFFFF", 16)

priv = int(json.load(open("/tmp/dh.json"))["priv"], 16)

A = int("")
ticket = b"7e1b1686ff9c157c"
frame = base64.b64decode("veHL06pWfgR3SkHwiGU1ZdmPFgMQbhGDJtla4dH/CbsOb6/nOoDMknDRMFbTJBAXtUhNisbLpU7IRnIZIN2cjKp/z8QZuof14U27p/diZwIsnGQ94A==")

shared = pow(A, priv, P)
key = hashlib.sha256(shared.to_bytes(256, "big") + ticket + b"B3LAY-7Q4M").digest()
print("frame len", len(frame))
nonce, ct, tag = frame[:12], frame[12:-16], frame[-16:]
c = AES.new(key, AES.MODE_GCM, nonce=nonce)
c.update(ticket)
pt = c.decrypt_and_verify(ct, tag)
print("PLAINTEXT:", pt)
